-- K04 shelf-company signature: 1989-98 vs 1999-2003 formations at the builder's 23 addresses, other 1000+ addresses, and everywhere else. Renamed after formation, ever filed an annual return or accounts, dissolved, dissolved within 3 years, median life, top object code
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, COMPANY_NAME nm, COMPANY_TYPE ty, COMPANY_STATUS st, REGISTERED_ADDRESS ra, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
ac AS (SELECT a2, COUNT(*) an FROM m GROUP BY 1),
r AS (SELECT TRIM(COMPANY_NUM) rid, TRY_TO_DATE(TRIM(COMPANY_REG_DATE),'YYYY-MM-DD') rd, TRY_TO_DATE(TRIM(LAST_AR_DATE),'YYYY-MM-DD') ar, TRY_TO_DATE(TRIM(LAST_ACCOUNTS_DATE),'YYYY-MM-DD') acc, TRY_TO_DATE(TRIM(COMP_DISSOLVED_DATE),'YYYY-MM-DD') dd, TRY_TO_DATE(TRIM(COMPANY_NAME_EFF_DATE),'YYYY-MM-DD') ned, TRIM(PRINC_OBJECT_CODE) poc FROM LIBRARY_RAW.LANDING.INTL_IE_CRO QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(COMPANY_NUM) ORDER BY _INGESTED_AT DESC) = 1),
j AS (
  SELECT m.*, ac.an, r.*,
         CASE WHEN m.a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET') THEN 'a_mass23' WHEN ac.an >= 1000 THEN 'b_other1000' ELSE 'c_rest' END cls,
         CASE WHEN m.y BETWEEN 1989 AND 1998 THEN 'p1_1989_98' WHEN m.y BETWEEN 1999 AND 2003 THEN 'p2_1999_03' END per
  FROM m JOIN ac ON ac.a2 = m.a2 LEFT JOIN r ON r.rid = m.id)
SELECT cls, per, COUNT(*) n, COUNT(rid) raw_matched, COUNT_IF(rd <> d) regdate_differs, COUNT_IF(ned > rd) renamed, COUNT_IF(ar IS NOT NULL) ever_ar,
       COUNT_IF(acc IS NOT NULL) ever_acc, COUNT_IF(dd IS NOT NULL) dissolved, COUNT_IF(DATEDIFF('day', rd, dd) <= 1095) diss_3y,
       ROUND(MEDIAN(DATEDIFF('day', rd, dd)) / 365.25, 1) med_life_y, MODE(poc) top_poc, COUNT_IF(poc = MODE(poc) OVER (PARTITION BY cls, per)) top_poc_n,
       COUNT_IF(REGEXP_LIKE(UPPER(nm), '.*(INTERNATIONAL|TRADING|HOLDING|INVESTMENT|IMPORT|EXPORT|FINANCE|CAPITAL).*')) intlish_name,
       COUNT_IF(st ILIKE 'Normal%') live
FROM j WHERE per IS NOT NULL GROUP BY 1,2 ORDER BY 1,2;

-- K05 when were they dissolved? Dissolution year for 1989-98 formations, the 23 addresses vs everywhere else
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, COMPANY_NAME nm, COMPANY_TYPE ty, COMPANY_STATUS st, REGISTERED_ADDRESS ra, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
r AS (SELECT TRIM(COMPANY_NUM) rid, TRY_TO_DATE(TRIM(COMPANY_REG_DATE),'YYYY-MM-DD') rd, TRY_TO_DATE(TRIM(LAST_AR_DATE),'YYYY-MM-DD') ar, TRY_TO_DATE(TRIM(LAST_ACCOUNTS_DATE),'YYYY-MM-DD') acc, TRY_TO_DATE(TRIM(COMP_DISSOLVED_DATE),'YYYY-MM-DD') dd, TRY_TO_DATE(TRIM(COMPANY_NAME_EFF_DATE),'YYYY-MM-DD') ned, TRIM(PRINC_OBJECT_CODE) poc FROM LIBRARY_RAW.LANDING.INTL_IE_CRO QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(COMPANY_NUM) ORDER BY _INGESTED_AT DESC) = 1),
j AS (SELECT IFF(m.a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET'), 'a_mass23', 'c_rest') cls, YEAR(r.dd) dy FROM m LEFT JOIN r ON r.rid = m.id WHERE m.y BETWEEN 1989 AND 1998)
SELECT cls, dy, COUNT(*) n FROM j GROUP BY 1,2 ORDER BY 1,2;

-- K06 formed there, or moved in later? Share of companies whose next or previous company number sits at the same address key (batch formation signature), by class and period
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, COMPANY_NAME nm, COMPANY_TYPE ty, COMPANY_STATUS st, REGISTERED_ADDRESS ra, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
ac AS (SELECT a2, COUNT(*) an FROM m GROUP BY 1),
s AS (SELECT TRY_TO_NUMBER(id) n, y, a2, LAG(a2) OVER (ORDER BY TRY_TO_NUMBER(id)) pk, LEAD(a2) OVER (ORDER BY TRY_TO_NUMBER(id)) nk FROM m WHERE TRY_TO_NUMBER(id) IS NOT NULL),
yk AS (SELECT y, a2, COUNT(*) k, SUM(COUNT(*)) OVER (PARTITION BY y) ny FROM m GROUP BY 1,2)
SELECT CASE WHEN s.a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET') THEN 'a_mass23' WHEN ac.an >= 1000 THEN 'b_other1000' ELSE 'c_rest' END cls,
       CASE WHEN s.y BETWEEN 1989 AND 1998 THEN 'p1_1989_98' WHEN s.y BETWEEN 1999 AND 2014 THEN 'p2_1999_2014' WHEN s.y >= 2015 THEN 'p3_2015_26' END per,
       COUNT(*) n, COUNT_IF(s.pk = s.a2 OR s.nk = s.a2) neighbour_same, ROUND(AVG(2 * yk.k / yk.ny), 4) chance_approx
FROM s JOIN ac ON ac.a2 = s.a2 JOIN yk ON yk.y = s.y AND yk.a2 = s.a2
WHERE s.y >= 1989 GROUP BY 1,2 ORDER BY 1,2;

-- K07 monthly, Jul 1997 - Dec 2000: all formations, at 1000+ addresses (builder's definition), at the 23 addresses, weekend-dated
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, COMPANY_NAME nm, COMPANY_TYPE ty, COMPANY_STATUS st, REGISTERED_ADDRESS ra, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
ac AS (SELECT a2, COUNT(*) an FROM m GROUP BY 1)
SELECT DATE_TRUNC('month', m.d)::date mo, COUNT(*) n, COUNT_IF(ac.an >= 1000) at1000, COUNT_IF(m.a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET')) mass23, COUNT_IF(DAYOFWEEKISO(m.d) >= 6) wkend
FROM m JOIN ac ON ac.a2 = m.a2 WHERE m.d BETWEEN '1997-07-01' AND '2000-12-31' GROUP BY 1 ORDER BY 1;

-- K08 name samples: 15 hash-picked 1990s companies at each of the top 3 addresses, and 15 from everywhere else in 1992
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, COMPANY_NAME nm, COMPANY_TYPE ty, COMPANY_STATUS st, REGISTERED_ADDRESS ra, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
g AS (SELECT m.*, CASE WHEN a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE') THEN a2 WHEN a2 NOT IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET') AND y = 1992 THEN 'REST_1992' END grp FROM m WHERE y BETWEEN 1990 AND 1999)
SELECT grp, id, d, nm, ty, st, LEFT(ra, 70) ra FROM g WHERE grp IS NOT NULL
QUALIFY ROW_NUMBER() OVER (PARTITION BY grp ORDER BY HASH(id)) <= 15 ORDER BY grp, id
